private val allowedHosts = setOf("app.example.com")

fun routeFrom(uri: Uri?): Route? {
    val host = uri?.host ?: return null
    if (host !in allowedHosts) return null

    return when (uri.pathSegments.firstOrNull()) {
        "order" -> uri.pathSegments.getOrNull(1)
            ?.takeIf { it.matches(Regex("[A-Za-z0-9_-]{1,32}")) }
            ?.let(Route::OrderDetail)
        "profile" -> Route.Profile
        else -> null
    }
}

