fun parseAge(input: String?): Int? {
    val raw = input?.trim() ?: return null
    if (raw.isEmpty() || !raw.all { it.isDigit() }) return null

    val age = raw.toIntOrNull() ?: return null
    return age.takeIf { it in 0..150 }
}

