fun buildDetailRoute(rawId: String?, source: String?): DetailRoute? {
    val id = rawId?.trim()
        ?.takeIf { it.matches(Regex("[A-Za-z0-9_-]{1,32}")) }
        ?: return null

    val safeSource = source?.trim()?.takeIf { it.isNotEmpty() } ?: "unknown"
    return DetailRoute(id, safeSource)
}

