fun reduce(state: UiState, action: Action): UiState = when (action) {
    Action.Load -> state.copy(loading = true, error = null)
    is Action.Success -> state.copy(loading = false, orders = action.orders, error = null)
    is Action.Failure -> state.copy(loading = false, error = action.message)
}

