import kotlin.math.ceil

data class FrameStats(val jankCount: Int, val p95: Long, val total: Int)

fun summarizeFrames(framesMs: List<Long>, budgetMs: Long): FrameStats {
    if (framesMs.isEmpty()) return FrameStats(0, 0, 0)

    val sorted = framesMs.sorted()
    val index = (ceil(sorted.size * 0.95).toInt() - 1)
        .coerceIn(0, sorted.lastIndex)
    val jank = framesMs.count { it > budgetMs }
    return FrameStats(jank, sorted[index], framesMs.size)
}

